import React, { useEffect, useState } from "react";
import axios from "axios";
import { useParams, useNavigate } from "react-router-dom";

const UserGig = () => {
  const { gigId } = useParams();
  const [gig, setGig] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchGig = async () => {
      try {
        const response = await axios.get(`http://localhost:5000/api/gigs/${gigId}`);
        setGig(response.data);
      } catch (error) {
        console.error("Error fetching gig:", error);
      }
    };

    fetchGig();
  }, [gigId]);

  const handleViewProfile = () => {
    if (gig?.userId) {
      navigate(`/profile/${gig.userId}`);
    }
  };

  if (!gig) return <p>Loading...</p>;

  return (
    <div style={{ maxWidth: "420px", margin: "40px auto", padding: "24px", boxShadow: "0 2px 8px rgba(0,0,0,0.1)", borderRadius: "12px", backgroundColor: "#fff" }}>
      <h2 style={{ color: "#f97316", textAlign: "center", marginBottom: "24px" }}>GIG POSTING</h2>

      <label><strong>Title</strong></label>
      <input type="text" value={gig.title} readOnly style={inputStyle} />

      <label><strong>Gig Type</strong></label>
      <input type="text" value={gig.gigType} readOnly style={inputStyle} />

      <label><strong>Genre</strong></label>
      <input type="text" value={Array.isArray(gig.genre) ? gig.genre.join(", ") : gig.genre} readOnly style={inputStyle} />

      <label><strong>City</strong></label>
      <input type="text" value={gig.city} readOnly style={inputStyle} />

      <label><strong>Description</strong></label>
      <textarea value={gig.description} readOnly style={textAreaStyle} />

      <label><strong>Date Posted</strong></label>
      <input type="text" value={gig.datePosted?.split("T")[0]} readOnly style={inputStyle} />

      <label><strong>Expires</strong></label>
      <input type="text" value={gig.expiryDate?.split("T")[0]} readOnly style={inputStyle} />

      <label><strong>Posted By</strong></label>
      <input type="text" value={gig.username} readOnly style={inputStyle} />

      <button onClick={handleViewProfile} style={buttonStyle}>
        View User Profile
      </button>
    </div>
  );
};

const inputStyle = {
  width: "100%",
  padding: "10px",
  marginBottom: "12px",
  borderRadius: "6px",
  border: "1px solid #ccc",
};

const textAreaStyle = {
  ...inputStyle,
  height: "80px",
  resize: "none",
};

const buttonStyle = {
  backgroundColor: "#f97316",
  color: "#fff",
  padding: "10px 20px",
  border: "none",
  borderRadius: "6px",
  marginTop: "16px",
  width: "100%",
  cursor: "pointer",
};

export default UserGig;
